args.initial_content:
'use client';

import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { useBuilderStore } from '@/hooks';
import { useAiActions } from '@/modules/ai-content/adapters/hooks/report-mode/use-ai-actions';
import { cn } from '@/infrastructure/utils/cn';
import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { GripVertical, Link as LinkIcon, Loader2, Sparkles } from 'lucide-react';
import React from 'react';
import { Checkbox } from '@/components/ui/checkbox';
import { Section } from '@/modules/ai-content/domain/entities/Section';
import { type Project } from '@/modules/projects/domain/entities/Project';
import { motion } from 'framer-motion';

interface SectionAccordionItemProps {
    section: Section;
    chapterIndex: number;
    sectionIndex: number;
    isProjectBuildMode: boolean;
    isSelected: boolean;
    isActive: boolean;
    onActivate: (sectionId: string, multiSelect?: boolean) => void;
    toggleSectionSelection: (sectionId: string) => void;
}

export function SectionAccordionItem({
    section,
    chapterIndex,
    sectionIndex,
    isProjectBuildMode,
    isSelected,
    isActive,
    onActivate,
    toggleSectionSelection,
}: SectionAccordionItemProps) {
    const { project } = useBuilderStore();

    const { generateSectionMutation } = useAiActions();

    const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: section.id });

    const style: React.CSSProperties = {
        transform: CSS.Transform.toString(transform),
        transition,
        zIndex: isDragging ? 20 : 0,
        position: 'relative',
    };

    if (!section) return null;

    const isGenerating = generateSectionMutation?.isPending && generateSectionMutation.variables === section.id;

    const getContextNames = (proj: Project | null, sec: Section): string[] => {
        if (!proj || !sec.context) return [];

        const sectionNames = Object.keys(sec.context.sections || {}).map(id => proj?.getSection(id)?.title || 'Untitled Section');
        const fileNames = Object.keys(sec.context.externalContext || {}).map(id => proj?.externalContext?.find(f => f.id === id)?.fileName || 'Untitled File');

        return [...sectionNames, ...fileNames];
    };

    const contextNames = getContextNames(project, section);
    const totalContext = contextNames.length;

    const handleActivate = (e: React.MouseEvent) => {
        onActivate(section.id, e.shiftKey || e.metaKey || e.ctrlKey);
    };

    return (
        <div
            ref={setNodeRef}
            style={style}
            {...attributes}
            className={cn(
                "group/item relative rounded-xl border transition-all duration-300 ease-out",
                isActive 
                    ? "border-primary/40 bg-primary/[0.03] shadow-[0_0_20px_rgba(var(--primary),0.08)] ring-1 ring-primary/20 -translate-y-[1px]" 
                    : "border-border/40 bg-card/50 hover:border-primary/20 hover:bg-muted/5 shadow-sm"
            )}
        >
            <div
                className={cn(
                    "flex items-center gap-3 px-3 py-2.5 cursor-pointer select-none",
                )}
                onClick={handleActivate}
            >
                {isProjectBuildMode && (
                    <div className="flex items-center shrink-0" onClick={(e) => { e.stopPropagation(); toggleSectionSelection(section.id); }}>
                        <Checkbox
                            checked={isSelected}
                            aria-label={`Select section ${section.title}`}
                            className="h-3.5 w-3.5 rounded-sm border-muted-foreground/30 data-[state=checked]:bg-primary data-[state=checked]:border-primary"
                        />
                    </div>
                )}

                <div className="flex items-center gap-2 flex-1 min-w-0">
                    {listeners && (
                        <div 
                            {...listeners} 
                            className="flex items-center gap-1.5 text-muted-foreground/40 transition-colors hover:text-primary shrink-0 cursor-grab active:cursor-grabbing"
                            onClick={(e) => e.stopPropagation()}
                        >
                            <span className="text-[9px] font-bold w-6 text-center tabular-nums opacity-60">
                                {chapterIndex >= 0 ? `${chapterIndex + 1}.${sectionIndex + 1}` : `${sectionIndex + 1}`}
                            </span>
                            <GripVertical className="h-3.5 w-3.5 opacity-50 group-hover/item:opacity-100 transition-opacity" />
                        </div>
                    )}

                    <div className="flex items-center gap-2.5 flex-1 min-w-0">
                        {isGenerating ? (
                            <div className="relative shrink-0">
                                <Loader2 className="h-3 w-3 animate-spin text-primary" />
                                <div className="absolute inset-0 blur-sm bg-primary/20 animate-pulse rounded-full" />
                            </div>
                        ) : (
                            <div className={cn(
                                "h-1.5 w-1.5 rounded-full shrink-0 transition-all duration-500",
                                isActive ? "bg-primary scale-125 shadow-[0_0_8px_rgba(var(--primary),0.6)]" : "bg-muted-foreground/20"
                            )} />
                        )}

                        <span className={cn(
                            "text-[11px] font-bold tracking-tight truncate flex-1 transition-colors duration-300",
                            isActive ? "text-foreground" : "text-muted-foreground/80 group-hover/item:text-foreground"
                        )}>
                            {section.title}
                        </span>
                    </div>

                    <div className="flex items-center gap-1.5 shrink-0">
                        {totalContext > 0 && (
                            <TooltipProvider>
                                <Tooltip>
                                    <TooltipTrigger asChild>
                                        <motion.div 
                                            initial={false}
                                            animate={isActive ? { scale: [1, 1.1, 1] } : {}}
                                            transition={{ repeat: Infinity, duration: 2 }}
                                            className="flex items-center gap-1 rounded-full bg-primary/10 px-2 py-0.5 text-primary ring-1 ring-primary/20 hover:bg-primary/20 transition-colors"
                                        >
                                            <LinkIcon className="h-2.5 w-2.5" />
                                            <span className="text-[9px] font-bold tabular-nums">{totalContext}</span>
                                        </motion.div>
                                    </TooltipTrigger>
                                    <TooltipContent side="top" className="border-primary/20 bg-background/95 backdrop-blur-md">
                                        <div className="text-[10px] font-medium space-y-1.5 p-1">
                                            <p className="border-b border-primary/10 pb-1 mb-1.5 uppercase tracking-widest text-[8px] font-bold text-primary flex items-center gap-1.5">
                                                <Sparkles className="h-2.5 w-2.5" />
                                                Linked Context
                                            </p>
                                            {contextNames.map((name, i) => (
                                                <div key={name + i} className="flex items-center gap-2 max-w-[180px]">
                                                    <div className="h-1 w-1 rounded-full bg-primary/40" />
                                                    <span className="truncate">{name}</span>
                                                </div>
                                            ))}
                                        </div>
                                    </TooltipContent>
                                </Tooltip>
                            </TooltipProvider>
                        )}
                    </div>
                </div>
            </div>

            {/* Visual focus border for active item */}
            {isActive && (
                <motion.div 
                    layoutId="active-section-indicator"
                    className="absolute inset-0 rounded-xl border-primary/40 pointer-events-none"
                    transition={{ type: 'spring', bounce: 0.2, duration: 0.6 }}
                />
            )}
        </div>
    );
};

'use client';

import { Button } from '@/components/ui/button';
import { Chapter } from '@/modules/ai-content/domain/entities/Chapter';
import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import {
  GripVertical,
  PlusCircle,
  ChevronDown,
  Hash,
} from 'lucide-react';
import React, { useMemo, useState } from 'react';
import { Checkbox } from "@/components/ui/checkbox";
import { SectionAccordionItem } from './SectionAccordionItem';
import { useBuilderStore } from "@/hooks";
import { cn } from '@/infrastructure/utils/cn';
import { motion, AnimatePresence } from 'framer-motion';

interface SortableChapterItemProps {
  chapter: Chapter;
  index: number;
  isProjectBuildMode: boolean;
  selectedSectionsForBuild: Set<string>;
  toggleChapterSelection: (chapterId: string, select: boolean) => void;
  toggleSectionSelection: (sectionId: string) => void;
  activeSectionId: string | null;
  selectedSectionIds?: string[];
  onActivateSection: (sectionId: string, multiSelect?: boolean) => void;
  onActivate?: () => void;
  isActive?: boolean;
}

export function SortableChapterItem({
  chapter,
  index,
  isProjectBuildMode,
  selectedSectionsForBuild,
  toggleChapterSelection,
  toggleSectionSelection,
  activeSectionId,
  selectedSectionIds = [],
  onActivateSection,
  onActivate,
  isActive,
}: SortableChapterItemProps) {
    const { 
        updateProject
    } = useBuilderStore(state => ({
        updateProject: state.updateProject,
    }));

  const [isCollapsed, setIsCollapsed] = useState(false);
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: chapter.id });

  const style: React.CSSProperties = {
    transform: CSS.Transform.toString(transform),
    transition,
    zIndex: isDragging ? 30 : 0,
    position: 'relative',
  };

  const sectionsInChapter = chapter.sections;
  const isAllSectionsSelected = useMemo(() => {
    if (sectionsInChapter.length === 0) return false;
    return sectionsInChapter.every(s => selectedSectionsForBuild.has(s.id));
  }, [sectionsInChapter, selectedSectionsForBuild]);

  const isSomeSectionsSelected = useMemo(() => {
    if (sectionsInChapter.length === 0) return false;
    const hasSelected = sectionsInChapter.some(s => selectedSectionsForBuild.has(s.id));
    return hasSelected && !isAllSectionsSelected;
  }, [sectionsInChapter, selectedSectionsForBuild, isAllSectionsSelected]);

  const handleAddSection = (chapterId: string) => {
    updateProject(p => p.addSectionToChapter(chapterId, 'Untitled Section'));
  }

  return (
    <div ref={setNodeRef} style={style} {...attributes} className="group/chapter-container">
      <div className={cn(
        "relative bg-card/40 border rounded-2xl shadow-sm overflow-hidden transition-all duration-300",
        isActive 
            ? "border-primary/40 bg-primary/[0.02] shadow-[0_4px_20px_rgba(0,0,0,0.04)] ring-1 ring-primary/10" 
            : "border-border/60 hover:border-primary/20 hover:shadow-md"
      )}>
        <div 
          className={cn(
            "flex items-center px-4 py-3.5 cursor-pointer border-b transition-colors",
            isActive ? "bg-primary/[0.04] border-primary/10" : "bg-muted/10 hover:bg-muted/20 border-border/40"
          )}
          onClick={() => onActivate?.()}
        >
          {isProjectBuildMode && (
            <div className="flex items-center gap-2 mr-3" onClick={(e) => e.stopPropagation()}>
              <Checkbox
                id={`select-chapter-${chapter.id}`}
                checked={isAllSectionsSelected}
                aria-checked={isSomeSectionsSelected ? 'mixed' : isAllSectionsSelected}
                onCheckedChange={(checked: any) => toggleChapterSelection(chapter.id, !!checked)}
                className="h-4 w-4 rounded-md"
              />
            </div>
          )}

          <div className="flex-1 py-0 min-w-0">
            <div className="flex items-center gap-3 flex-1 min-w-0 group">
              {listeners && (
                <div 
                    {...listeners} 
                    className="p-1.5 rounded-lg cursor-grab touch-none -ml-2 flex items-center gap-2 text-muted-foreground/40 transition-all hover:bg-background/80 hover:text-primary active:cursor-grabbing" 
                    onClick={(e) => e.stopPropagation()}
                >
                  <Hash className="h-3 w-3" />
                  <span className="text-[10px] w-4 text-center font-black tabular-nums">{index + 1}</span>
                  <GripVertical className="h-4 w-4 opacity-40 group-hover:opacity-100" />
                </div>
              )}

              <div className="flex flex-col flex-1 min-w-0 text-left">
                <span className={cn(
                    "text-[11px] font-black uppercase tracking-[0.15em] transition-colors duration-300",
                    isActive ? "text-primary" : "text-muted-foreground/80 group-hover:text-primary"
                )}>
                    {chapter.title || 'UNTITLED CHAPTER'}
                </span>
                <span className="text-[9px] font-bold text-muted-foreground/40 uppercase tracking-widest mt-0.5">
                    {sectionsInChapter.length} Sections Integrated
                </span>
              </div>

              <Button
                variant="ghost"
                size="icon"
                className={cn(
                    "h-8 w-8 rounded-xl transition-all duration-300",
                    isActive ? "bg-primary/10 text-primary" : "hover:bg-primary/5 hover:text-primary text-muted-foreground/60"
                )}
                onClick={(e) => {
                  e.stopPropagation();
                  setIsCollapsed(!isCollapsed);
                }}
              >
                <ChevronDown className={cn(
                  "h-4 w-4 transition-transform duration-500 cubic-bezier(0.4, 0, 0.2, 1)",
                  isCollapsed && "-rotate-90"
                )} />
              </Button>
            </div>
          </div>
        </div>

        <AnimatePresence initial={false}>
          {!isCollapsed && (
            <motion.div 
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: "auto", opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              transition={{ duration: 0.35, ease: [0.33, 1, 0.68, 1] }}
              className="overflow-hidden"
            >
              <div className="p-4 bg-muted/5 relative">
                {/* Visual depth vertical line */}
                <div className="absolute left-6 top-0 bottom-10 w-px bg-gradient-to-b from-border/60 via-primary/10 to-transparent" />

                <div className="w-full space-y-2.5 pl-6 rtl:pl-0 rtl:pr-6">
                  {chapter.sections.map((section, sectionIndex) => (
                    <SectionAccordionItem
                      key={section.id}
                      section={section}
                      sectionIndex={sectionIndex}
                      chapterIndex={index}
                      isProjectBuildMode={isProjectBuildMode}
                      isSelected={selectedSectionsForBuild.has(section.id)}
                      toggleSectionSelection={toggleSectionSelection}
                      isActive={selectedSectionIds.includes(section.id)}
                      onActivate={onActivateSection}
                    />
                  ))}

                  <Button 
                    size="sm" 
                    variant="ghost" 
                    onClick={(e) => { e.stopPropagation(); handleAddSection(chapter.id); }} 
                    className="w-full h-9 text-[9px] font-black uppercase tracking-[0.2em] gap-2 hover:bg-primary/5 hover:text-primary border border-dashed border-border/60 hover:border-primary/30 transition-all duration-300 rounded-xl mt-4 text-muted-foreground/60"
                  >
                    <PlusCircle className="h-3.5 w-3.5" />
                    Integrate New Section
                  </Button>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

'use client';

import { Button } from '@/components/ui/button';
import { useReportGenerationTools } from '@/modules/ai-content/adapters/hooks/report-mode/use-report-generation-tools';
import {
  DndContext,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors,
} from '@dnd-kit/core';
import {
  SortableContext,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable';
import {
  Building,
  PlusCircle,
  XCircle,
  Zap,
  Layers,
  Sparkles,
  ChevronRight,
} from 'lucide-react';
import { useMemo } from "react";
import { Checkbox } from "@/components/ui/checkbox";
import { Label } from "@/components/ui/label";
import { BuildProjectDialog } from "../dialogs/BuildProjectDialog";
import { Chapter } from '@/modules/ai-content/domain/entities/Chapter';
import { Section } from '@/modules/ai-content/domain/entities/Section';
import { ScrollArea } from "@/components/ui/scroll-area";
import { SectionAccordionItem } from "./SectionAccordionItem";
import { SortableChapterItem } from "./SortableChapterItem";
import { cn } from '@/infrastructure/utils/cn';
import { motion, AnimatePresence } from 'framer-motion';

interface GenerationToolsProps {
  selectedSectionIds: string[];
  activeChapterId?: string | null;
  onActiveSectionChange: (sectionId: string | null, multiSelect?: boolean) => void;
  onActiveChapterChange?: (chapterId: string | null) => void;
}

export default function GenerationTools({
  selectedSectionIds,
  activeChapterId,
  onActiveSectionChange,
  onActiveChapterChange,
}: GenerationToolsProps) {
  const {
    t,
    handleDragEnd,
    isBuildProjectDialogOpen,
    setIsBuildProjectDialogOpen,
    project,
    isProjectBuildMode,
    enterProjectBuildMode,
    exitProjectBuildMode,
    selectedSectionsForBuild,
    toggleChapterSelection,
    toggleSectionSelection,
    toggleSelectAll,
    onGenerateProject,
    projectMutation,
    chaptersToBuild,
    handleAddChapter,
  } = useReportGenerationTools();

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8,
      },
    })
  );

  const totalSelectableSections = project?.sections.length || 0;
  const isAllSelected = useMemo(() => totalSelectableSections > 0 && selectedSectionsForBuild.size === totalSelectableSections, [totalSelectableSections, selectedSectionsForBuild]);
  const isIndeterminate = useMemo(() => selectedSectionsForBuild.size > 0 && !isAllSelected, [selectedSectionsForBuild, isAllSelected]);

  const canBuildProject = project && project.content.length > 0;

  const handleActivateSection = (sectionId: string, multiSelect?: boolean) => {
    onActiveSectionChange(sectionId, multiSelect);
  };

  const handleActivateChapter = (chapterId: string) => {
    onActiveChapterChange?.(chapterId);
  };

  return (
    <>
      <BuildProjectDialog
        isOpen={isBuildProjectDialogOpen}
        onOpenChange={setIsBuildProjectDialogOpen}
        chaptersToBuild={chaptersToBuild}
        onGenerateProject={onGenerateProject}
        isLoading={projectMutation.isPending}
      />
      <div className="flex flex-col h-full overflow-hidden bg-background/50">
        <header className="space-y-4 px-6 pt-6 pb-4 border-b border-border/40 relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-20 transition-opacity duration-700">
            <Layers className="h-16 w-16" />
          </div>

          <div className="flex flex-col space-y-1 relative z-10">
            <h4 className="text-[11px] font-black uppercase tracking-[0.2em] text-primary flex items-center gap-2">
              <Zap className="h-3 w-3" />
              {t('builder.reportGenerator.toolsTitle')}
            </h4>
            <p className="text-[10px] text-muted-foreground italic leading-relaxed font-medium opacity-80">
              {t('builder.reportGenerator.toolsDesc')}
            </p>
          </div>

          <Button 
            onClick={handleAddChapter} 
            variant="outline" 
            size="sm" 
            className="w-full font-black h-10 border-dashed hover:border-primary/40 hover:bg-primary/5 transition-all duration-300 rounded-xl uppercase tracking-widest text-[9px] relative group overflow-hidden"
          >
            <PlusCircle className="me-2 h-3.5 w-3.5 text-primary group-hover:scale-110 transition-transform" />
            Initialize New Chapter
            <motion.div 
              className="absolute inset-0 bg-primary/5 translate-y-full group-hover:translate-y-0 transition-transform duration-500" 
            />
          </Button>
        </header>

        <div className="flex-grow flex flex-col min-h-0 relative">
          <div className="absolute inset-0 z-0 pointer-events-none opacity-20" style={{ backgroundImage: 'radial-gradient(circle at 2px 2px, hsl(var(--border)) 1px, transparent 0)', backgroundSize: '24px 24px' }} />

          <div className="relative z-10 h-full flex flex-col pt-4">
            <AnimatePresence>
              {isProjectBuildMode && (
                <motion.div 
                  initial={{ height: 0, opacity: 0, marginBottom: 0 }}
                  animate={{ height: 'auto', opacity: 1, marginBottom: 16 }}
                  exit={{ height: 0, opacity: 0, marginBottom: 0 }}
                  className="px-6 overflow-hidden"
                >
                  <div className="flex items-center gap-4 p-4 rounded-2xl border bg-primary/[0.04] border-primary/20 backdrop-blur-xl shadow-[0_4px_20px_rgba(var(--primary),0.1)] ring-1 ring-primary/20 group/build-hud">
                    <div className="relative">
                      <Checkbox
                        id="select-all-chapters"
                        checked={isAllSelected}
                        onCheckedChange={(checked: any) => toggleSelectAll(!!checked)}
                        aria-checked={isIndeterminate ? 'mixed' : isAllSelected}
                        className="h-4.5 w-4.5 rounded-md border-primary/40 data-[state=checked]:bg-primary"
                      />
                      <Sparkles className="absolute -top-1.5 -right-1.5 h-2.5 w-2.5 text-primary opacity-0 group-hover/build-hud:opacity-100 transition-opacity duration-500" />
                    </div>
                    <div className="flex flex-col">
                      <Label htmlFor="select-all-chapters" className="font-black text-[10px] uppercase tracking-[0.15em] text-primary cursor-pointer">
                        Manifest Selection Mode
                      </Label>
                      <span className="text-[8px] font-bold text-primary/60 uppercase tracking-widest mt-0.5">
                        {selectedSectionsForBuild.size} / {totalSelectableSections} Sections Prepared
                      </span>
                    </div>
                  </div>
                </motion.div>
              )}
            </AnimatePresence>

            <ScrollArea className="flex-grow px-6">
              <div className="pb-32">
                <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
                  <SortableContext items={(project?.content || []).map(c => c.id)} strategy={verticalListSortingStrategy}>
                    <div className="w-full space-y-4">
                      {(project?.content || []).map((item, index) => {
                        if (item instanceof Chapter) {
                          return (
                            <SortableChapterItem
                              chapter={item}
                              index={index}
                              key={item.id}
                              isProjectBuildMode={isProjectBuildMode}
                              selectedSectionsForBuild={selectedSectionsForBuild}
                              toggleChapterSelection={toggleChapterSelection}
                              toggleSectionSelection={toggleSectionSelection}
                              activeSectionId={selectedSectionIds.length > 0 ? selectedSectionIds[0] : null}
                              onActivateSection={handleActivateSection}
                              onActivate={() => handleActivateChapter(item.id)}
                              isActive={activeChapterId === item.id}
                              selectedSectionIds={selectedSectionIds}
                            />
                          )
                        }
                        if (item instanceof Section) {
                          return (
                            <SectionAccordionItem
                              key={item.id}
                              section={item}
                              sectionIndex={index}
                              chapterIndex={-1}
                              isProjectBuildMode={isProjectBuildMode}
                              isSelected={selectedSectionsForBuild.has(item.id)}
                              toggleSectionSelection={toggleSectionSelection}
                              isActive={selectedSectionIds.includes(item.id)}
                              onActivate={handleActivateSection}
                            />
                          );
                        }
                        return null;
                      })}
                    </div>
                  </SortableContext>
                </DndContext>
              </div>
            </ScrollArea>

            {/* Premium Sticky Action Bar */}
            <div className="absolute bottom-0 left-0 right-0 p-6 pt-12 bg-gradient-to-t from-background via-background/95 to-transparent z-40 pointer-events-none">
              <div className="flex gap-3 pointer-events-auto">
                <AnimatePresence mode="wait">
                  {isProjectBuildMode ? (
                    <motion.div 
                      key="build-mode-actions"
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      exit={{ opacity: 0, y: 20 }}
                      className="flex gap-2 w-full"
                    >
                      <Button onClick={exitProjectBuildMode} variant="secondary" size="sm" className="flex-1 font-black h-11 border bg-background/60 backdrop-blur-xl rounded-xl uppercase tracking-widest text-[9px] hover:bg-muted/80 transition-all border-border/40">
                        <XCircle className="mr-2 h-4 w-4" /> Terminate
                      </Button>
                      <Button
                        size="sm"
                        className="flex-[2] font-black h-11 shadow-[0_10px_30px_rgba(var(--primary),0.2)] rounded-xl uppercase tracking-[0.2em] text-[10px] bg-primary hover:opacity-90 transition-all relative overflow-hidden group"
                        onClick={() => setIsBuildProjectDialogOpen(true)}
                        disabled={selectedSectionsForBuild.size === 0 || projectMutation.isPending}
                      >
                        <Building className="mr-2 h-4 w-4 group-hover:scale-110 transition-transform" />
                        Execute Build ({selectedSectionsForBuild.size})
                        <ChevronRight className="ml-1 h-3 w-3 opacity-0 group-hover:opacity-100 -translate-x-2 group-hover:translate-x-0 transition-all" />
                      </Button>
                    </motion.div>
                  ) : canBuildProject && (
                    <motion.div 
                      key="standard-actions"
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      exit={{ opacity: 0, y: 20 }}
                      className="w-full"
                    >
                      <Button
                        size="sm"
                        className="w-full font-black h-11 shadow-[0_10px_25px_rgba(var(--primary),0.1)] rounded-xl uppercase tracking-[0.2em] text-[10px] bg-primary group relative overflow-hidden transition-all duration-500 hover:shadow-primary/30"
                        onClick={enterProjectBuildMode}
                        disabled={projectMutation.isPending}
                      >
                        <Building className="mr-2 h-4 w-4" />
                        Assemble Project Manifest
                        <div className="absolute inset-0 bg-white/10 -translate-x-full group-hover:translate-x-full transition-transform duration-1000 ease-in-out" />
                      </Button>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            </div>
          </div>
